                "Orders",
                "order_details"
            ],
            "time_dependent": true
        },
        "Order Fulfillment Time": {
            "type": "metric",
            "description": "Average days between OrderDate and ShippedDate",
            "formula": "AVG(julianday(Orders.ShippedDate) - julianday(Orders.OrderDate))",
            "tables": [
                "Orders"
            ]
        },
        "Employee Sales Performance": {
